static int failures, checks;

static void compare(const char *name, CFStringRef port, CFStringRef system)
{
    char mine[512], theirs[512];
    BOOL mineOk = port && CFStringGetCString(port, mine, sizeof mine, kCFStringEncodingUTF8);
    BOOL theirsOk = system && CFStringGetCString(system, theirs, sizeof theirs, kCFStringEncodingUTF8);
    checks++;
    if (mineOk != theirsOk || (mineOk && strcmp(mine, theirs) != 0)) {
        failures++;
        printf("DIFFERENT %s: port %s, host %s\n", name, mineOk ? mine : "(not a string)", theirsOk ? theirs : "(not a string)");
    }
}

